"""The signed-in user's personal todo list."""

from __future__ import annotations

import sqlite3

from fastapi import APIRouter, Depends, Query, Response, status
from pydantic import BaseModel

from app.db import get_db, row_to_dict, utc_now
from app.errors import bad_request, not_found
from app.pagination import PageParams, page_params, paginate
from app.security import CurrentUser, get_current_user

router = APIRouter(prefix="/api/todos", tags=["todos"])

TITLE_MAX = 200

class TodoOut(BaseModel):
 id: int
 title: str
 done: bool
 created_at: str
 updated_at: str

class TodoCreate(BaseModel):
 title: str

class TodoUpdate(BaseModel):
 title: str | None = None
 done: bool | None = None

def _clean_title(title: str) -> str:
 cleaned = title.strip()
 if not cleaned:
  raise bad_request("invalid_title", "A title is required.")
 if len(cleaned) > TITLE_MAX:
  raise bad_request("invalid_title", f"A title may be at most {TITLE_MAX} characters.")
 return cleaned

def _to_out(row: sqlite3.Row) -> TodoOut:
 return TodoOut(
  id=int(row["id"]),
  title=row["title"],
  done=bool(row["done"]),
  created_at=row["created_at"],
  updated_at=row["updated_at"],
 )

def _load(conn: sqlite3.Connection, todo_id: int, user_id: int) -> sqlite3.Row:
 row = conn.execute(
  "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ? AND user_id = ?",
  (todo_id, user_id),
 ).fetchone()
 if row is None:
  raise not_found("todo_not_found", "No such todo.")
 return row

@router.get("", summary="List your todos, newest first.")
def list_todos(
 done: bool | None = Query(default=None, description="Only open or only done todos."),
 page: PageParams = Depends(page_params),
 user: CurrentUser = Depends(get_current_user),
 conn: sqlite3.Connection = Depends(get_db),
) -> dict[str, object]:
 where = "user_id = ?"
 params: list[object] = [user.id]
 if done is not None:
  where += " AND done = ?"
  params.append(1 if done else 0)
 total = int(conn.execute(f"SELECT COUNT(*) FROM todos WHERE {where}", params).fetchone()[0])
 rows = conn.execute(
  f"SELECT id, title, done, created_at, updated_at FROM todos WHERE {where} "
  "ORDER BY created_at DESC, id DESC LIMIT ? OFFSET ?",
  [*params, page.limit, page.offset],
 ).fetchall()
 return paginate([_to_out(row) for row in rows], total, page)

@router.post("", response_model=TodoOut, status_code=status.HTTP_201_CREATED, summary="Add a todo.")
def create_todo(
 body: TodoCreate,
 user: CurrentUser = Depends(get_current_user),
 conn: sqlite3.Connection = Depends(get_db),
) -> TodoOut:
 title = _clean_title(body.title)
 now = utc_now()
 cur = conn.execute(
  "INSERT INTO todos (user_id, title, done, created_at, updated_at) VALUES (?, ?, 0, ?, ?)",
  (user.id, title, now, now),
 )
 row = _load(conn, int(cur.lastrowid), user.id)
 return _to_out(row)

@router.get("/{todo_id}", response_model=TodoOut, summary="One of your todos.")
def get_todo(
 todo_id: int,
 user: CurrentUser = Depends(get_current_user),
 conn: sqlite3.Connection = Depends(get_db),
) -> TodoOut:
 return _to_out(_load(conn, todo_id, user.id))

@router.patch("/{todo_id}", response_model=TodoOut, summary="Change a todo's title or state.")
def update_todo(
 todo_id: int,
 body: TodoUpdate,
 user: CurrentUser = Depends(get_current_user),
 conn: sqlite3.Connection = Depends(get_db),
) -> TodoOut:
 _load(conn, todo_id, user.id)
 sets: list[str] = []
 params: list[object] = []
 if body.title is not None:
  sets.append("title = ?")
  params.append(_clean_title(body.title))
 if body.done is not None:
  sets.append("done = ?")
  params.append(1 if body.done else 0)
 if not sets:
  raise bad_request("nothing_to_update", "Provide a title or done value.")
 sets.append("updated_at = ?")
 params.append(utc_now())
 params.extend([todo_id, user.id])
 conn.execute(f"UPDATE todos SET {', '.join(sets)} WHERE id = ? AND user_id = ?", params)
 return _to_out(_load(conn, todo_id, user.id))

@router.delete("/{todo_id}", status_code=status.HTTP_204_NO_CONTENT, summary="Delete a todo.")
def delete_todo(
 todo_id: int,
 user: CurrentUser = Depends(get_current_user),
 conn: sqlite3.Connection = Depends(get_db),
) -> Response:
 _load(conn, todo_id, user.id)
 conn.execute("DELETE FROM todos WHERE id = ? AND user_id = ?", (todo_id, user.id))
 return Response(status_code=status.HTTP_204_NO_CONTENT)
