import { apiFetch, ApiError, saveToken } from "./api.js";
import { formValues, showMessage, whileBusy } from "./ui.js";

const loginForm = document.getElementById("login-form");
const registerForm = document.getElementById("register-form");

function fail(error) {
const text = error instanceof ApiError ? error.message : "The service cannot be reached.";
showMessage(text, "error");
}

async function signIn(username, password) {
const result = await apiFetch("/api/auth/login", {
method: "POST",
body: { username, password },
auth: false,
});
saveToken(result.access_token);
window.location.href = "todos.html";
}

loginForm.addEventListener("submit", async (event) => {
event.preventDefault();
const values = formValues(loginForm);
await whileBusy(loginForm, async () => {
try {
await signIn(values.username, values.password);
} catch (error) {
fail(error);
}
});
});

registerForm.addEventListener("submit", async (event) => {
event.preventDefault();
const values = formValues(registerForm);
await whileBusy(registerForm, async () => {
try {
await apiFetch("/api/auth/register", {
method: "POST",
body: { username: values.username, password: values.password },
auth: false,
});
showMessage("Account created. Signing you in...", "success");
await signIn(values.username, values.password);
} catch (error) {
fail(error);
}
});
});
