import { apiFetch, ApiError, clearToken, isSignedIn } from "./api.js";
import { clear, el, formatTime, formValues, showMessage, whileBusy } from "./ui.js";

if (!isSignedIn()) {
window.location.href = "login.html";
}

const list = document.getElementById("list");
const filter = document.getElementById("filter");
const prev = document.getElementById("prev");
const next = document.getElementById("next");
const addForm = document.getElementById("add-form");
const whoami = document.getElementById("whoami");
const signout = document.getElementById("signout");

let offset = 0;
let limit = 20;
let total = 0;

function fail(error) {
if (error instanceof ApiError && error.status === 401) {
clearToken();
window.location.href = "login.html";
return;
}
const text = error instanceof ApiError ? error.message : "The service cannot be reached.";
showMessage(text, "error");
}

function doneFilter() {
if (filter.value === "open") return false;
if (filter.value === "done") return true;
return null;
}

async function loadUser() {
try {
const me = await apiFetch("/api/auth/me");
whoami.textContent = me.username;
} catch (error) {
fail(error);
}
}

async function toggle(todo) {
try {
await apiFetch(`/api/todos/${todo.id}`, { method: "PATCH", body: { done: !todo.done } });
await load();
} catch (error) {
fail(error);
}
}

async function rename(todo) {
const title = window.prompt("New title", todo.title);
if (title === null) return;
try {
await apiFetch(`/api/todos/${todo.id}`, { method: "PATCH", body: { title } });
await load();
} catch (error) {
fail(error);
}
}

async function remove(todo) {
if (!window.confirm(`Delete "${todo.title}"?`)) return;
try {
await apiFetch(`/api/todos/${todo.id}`, { method: "DELETE" });
await load();
} catch (error) {
fail(error);
}
}

function renderItem(todo) {
const checkbox = el("input", { type: "checkbox" });
checkbox.checked = todo.done;
checkbox.addEventListener("change", () => toggle(todo));
const title = el("span", { class: "title" }, todo.title);
const meta = el("span", { class: "muted" }, formatTime(todo.created_at));
const renameBtn = el("button", { type: "button", class: "secondary" }, "Rename");
renameBtn.addEventListener("click", () => rename(todo));
const deleteBtn = el("button", { type: "button", class: "danger" }, "Delete");
deleteBtn.addEventListener("click", () => remove(todo));
return el(
"li",
{ class: todo.done ? "list-item done" : "list-item" },
checkbox,
el("span", { class: "grow" }, title, " ", meta),
renameBtn,
deleteBtn,
);
}

async function load() {
try {
const query = { limit, offset };
const done = doneFilter();
if (done !== null) query.done = done;
const page = await apiFetch("/api/todos", { query });
total = page.total;
limit = page.limit;
offset = page.offset;
clear(list);
if (page.items.length === 0) {
list.append(el("li", { class: "list-item muted" }, "No todos yet."));
}
for (const todo of page.items) {
list.append(renderItem(todo));
}
prev.disabled = offset <= 0;
next.disabled = offset + limit >= total;
} catch (error) {
fail(error);
}
}

addForm.addEventListener("submit", async (event) => {
event.preventDefault();
const values = formValues(addForm);
await whileBusy(addForm, async () => {
try {
await apiFetch("/api/todos", { method: "POST", body: { title: values.title } });
addForm.reset();
offset = 0;
await load();
} catch (error) {
fail(error);
}
});
});

filter.addEventListener("change", () => {
offset = 0;
load();
});

prev.addEventListener("click", () => {
offset = Math.max(0, offset - limit);
load();
});

next.addEventListener("click", () => {
offset += limit;
load();
});

signout.addEventListener("click", () => {
clearToken();
window.location.href = "login.html";
});

loadUser();
load();
